// Package gateway serves the public read-only accounts API.
package gateway

import (
	"encoding/json"
	"io"
	"net/http"
	"slices"
	"time"
)

// Account is one record the API serves.
type Account struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Cents  int64  `json:"cents"`
	Active bool   `json:"active"`
}

// NewServer returns the server for the public accounts API, listening on addr
// and serving the given accounts. Starting and stopping it is the caller's job.
//
// This server is the edge: it is published straight to the open internet with
// no proxy of any kind in front of it. Every client is anonymous, some are on
// mobile links that stall mid-request, many hold connections open long after
// they stop asking for anything, and a share of the traffic is there to find
// out what the process can be made to hold onto.
//
// It answers these requests and nothing else:
//
//	GET /healthz         200, body "ok"
//	GET /accounts        200, a JSON array of every account, ordered by ID
//	GET /accounts/{id}   200, the JSON object for that account; 404 if unknown
//
// GET /accounts also takes one optional query parameter, active, which is
// either "true" or "false" and restricts the array to accounts in that state.
// Any other value for it is a 400 whose body names the parameter.
//
// Any other path is a 404. A known path asked for with any method other than
// GET is a 405.
func NewServer(addr string, accounts []Account) *http.Server {
	accounts = slices.Clone(accounts)
	slices.SortStableFunc(accounts, func(a, b Account) int {
		if a.ID < b.ID {
			return -1
		}
		if a.ID > b.ID {
			return 1
		}
		return 0
	})

	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = io.WriteString(w, "ok")
	})
	mux.HandleFunc("HEAD /healthz", methodNotAllowed)
	mux.HandleFunc("GET /accounts", func(w http.ResponseWriter, r *http.Request) {
		var filtered []Account
		switch values := r.URL.Query()["active"]; len(values) {
		case 0:
			filtered = slices.Clone(accounts)
			if filtered == nil {
				filtered = []Account{}
			}
		case 1:
			var active bool
			switch values[0] {
			case "true":
				active = true
			case "false":
			default:
				http.Error(w, "invalid active parameter", http.StatusBadRequest)
				return
			}

			filtered = make([]Account, 0, len(accounts))
			for _, account := range accounts {
				if account.Active == active {
					filtered = append(filtered, account)
				}
			}
		default:
			http.Error(w, "invalid active parameter", http.StatusBadRequest)
			return
		}

		writeJSON(w, filtered)
	})
	mux.HandleFunc("HEAD /accounts", methodNotAllowed)
	mux.HandleFunc("GET /accounts/{id}", func(w http.ResponseWriter, r *http.Request) {
		id := r.PathValue("id")
		if id == "" {
			http.NotFound(w, r)
			return
		}
		for _, account := range accounts {
			if account.ID == id {
				writeJSON(w, account)
				return
			}
		}
		http.NotFound(w, r)
	})
	mux.HandleFunc("HEAD /accounts/{id}", methodNotAllowed)

	return &http.Server{
		Addr:                addr,
		Handler:             mux,
		ReadHeaderTimeout:   5 * time.Second,
		ReadTimeout:         15 * time.Second,
		WriteTimeout:        15 * time.Second,
		IdleTimeout:         60 * time.Second,
		MaxHeaderBytes:      1 << 20,
		MaxHeaderValueCount: 100,
	}
}

func methodNotAllowed(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Allow", http.MethodGet)
	http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
}

func writeJSON(w http.ResponseWriter, value any) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(value)
}

// Package gateway serves the public read-only accounts API.
package gateway

import (
	"encoding/json"
	"net/http"
	"slices"
	"strings"
	"time"
)

// Account is one record the API serves.
type Account struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Cents  int64  `json:"cents"`
	Active bool   `json:"active"`
}

// NewServer returns the server for the public accounts API, listening on addr
// and serving the given accounts. Starting and stopping it is the caller's job.
//
// This server is the edge: it is published straight to the open internet with
// no proxy of any kind in front of it. Every client is anonymous, some are on
// mobile links that stall mid-request, many hold connections open long after
// they stop asking for anything, and a share of the traffic is there to find
// out what the process can be made to hold onto.
//
// It answers these requests and nothing else:
//
//	GET /healthz         200, body "ok"
//	GET /accounts        200, a JSON array of every account, ordered by ID
//	GET /accounts/{id}   200, the JSON object for that account; 404 if unknown
//
// GET /accounts also takes one optional query parameter, active, which is
// either "true" or "false" and restricts the array to accounts in that state.
// Any other value for it is a 400 whose body names the parameter.
//
// Any other path is a 404. A known path asked for with any method other than
// GET is a 405.
func NewServer(addr string, accounts []Account) *http.Server {
	accounts = slices.Clone(accounts)
	slices.SortStableFunc(accounts, func(a, b Account) int {
		return strings.Compare(a.ID, b.ID)
	})

	byID := make(map[string]Account, len(accounts))
	for _, account := range accounts {
		byID[account.ID] = account
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		switch {
		case r.URL.Path == "/healthz":
			if !getOnly(w, r) {
				return
			}
			w.WriteHeader(http.StatusOK)
			_, _ = w.Write([]byte("ok"))
		case r.URL.Path == "/accounts":
			if !getOnly(w, r) {
				return
			}
			handleAccounts(w, r, accounts)
		case strings.HasPrefix(r.URL.Path, "/accounts/"):
			id := strings.TrimPrefix(r.URL.Path, "/accounts/")
			if id == "" || strings.Contains(id, "/") {
				http.NotFound(w, r)
				return
			}
			if !getOnly(w, r) {
				return
			}
			account, ok := byID[id]
			if !ok {
				http.NotFound(w, r)
				return
			}
			writeJSON(w, account)
		default:
			http.NotFound(w, r)
		}
	})

	return &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    1 << 20,
	}
}

func getOnly(w http.ResponseWriter, r *http.Request) bool {
	if r.Method == http.MethodGet {
		return true
	}
	w.Header().Set("Allow", http.MethodGet)
	w.WriteHeader(http.StatusMethodNotAllowed)
	return false
}

func handleAccounts(w http.ResponseWriter, r *http.Request, accounts []Account) {
	values, present := r.URL.Query()["active"]
	if present {
		if len(values) != 1 || (values[0] != "true" && values[0] != "false") {
			http.Error(w, "invalid query parameter: active\n", http.StatusBadRequest)
			return
		}
	}

	filtered := make([]Account, 0, len(accounts))
	for _, account := range accounts {
		if !present || (values[0] == "true") == account.Active {
			filtered = append(filtered, account)
		}
	}
	writeJSON(w, filtered)
}

func writeJSON(w http.ResponseWriter, value any) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(value)
}

// Package gateway serves the public read-only accounts API.
package gateway

import (
	"encoding/json"
	"net/http"
	"slices"
	"strings"
	"time"
)

// Account is one record the API serves.
type Account struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Cents  int64  `json:"cents"`
	Active bool   `json:"active"`
}

// NewServer returns the server for the public accounts API, listening on addr
// and serving the given accounts. Starting and stopping it is the caller's job.
//
// This server is the edge: it is published straight to the open internet with
// no proxy of any kind in front of it. Every client is anonymous, some are on
// mobile links that stall mid-request, many hold connections open long after
// they stop asking for anything, and a share of the traffic is there to find
// out what the process can be made to hold onto.
//
// It answers these requests and nothing else:
//
//	GET /healthz         200, body "ok"
//	GET /accounts        200, a JSON array of every account, ordered by ID
//	GET /accounts/{id}   200, the JSON object for that account; 404 if unknown
//
// GET /accounts also takes one optional query parameter, active, which is
// either "true" or "false" and restricts the array to accounts in that state.
// Any other value for it is a 400 whose body names the parameter.
//
// Any other path is a 404. A known path asked for with any method other than
// GET is a 405.
func NewServer(addr string, accounts []Account) *http.Server {
	ordered := slices.Clone(accounts)
	slices.SortFunc(ordered, func(a, b Account) int {
		return strings.Compare(a.ID, b.ID)
	})

	return &http.Server{
		Addr:                addr,
		Handler:             accountHandler{accounts: ordered},
		ReadHeaderTimeout:   5 * time.Second,
		ReadTimeout:         15 * time.Second,
		WriteTimeout:        15 * time.Second,
		IdleTimeout:         60 * time.Second,
		MaxHeaderBytes:      1 << 20,
		MaxHeaderValueCount: 100,
	}
}

type accountHandler struct {
	accounts []Account
}

func (h accountHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	switch {
	case r.URL.Path == "/healthz":
		if r.Method != http.MethodGet {
			methodNotAllowed(w)
			return
		}
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ok"))
	case r.URL.Path == "/accounts":
		if r.Method != http.MethodGet {
			methodNotAllowed(w)
			return
		}
		h.writeAccounts(w, r)
	case strings.HasPrefix(r.URL.Path, "/accounts/"):
		id := r.URL.Path[len("/accounts/"):]
		if id == "" || strings.Contains(id, "/") {
			http.NotFound(w, r)
			return
		}
		if r.Method != http.MethodGet {
			methodNotAllowed(w)
			return
		}
		h.writeAccount(w, r, id)
	default:
		http.NotFound(w, r)
	}
}

func (h accountHandler) writeAccounts(w http.ResponseWriter, r *http.Request) {
	accounts := make([]Account, 0, len(h.accounts))
	activeValues, hasActive := r.URL.Query()["active"]
	if hasActive {
		if len(activeValues) != 1 {
			http.Error(w, "invalid active parameter", http.StatusBadRequest)
			return
		}
		active := activeValues[0]
		var wantActive bool
		switch active {
		case "true":
			wantActive = true
		case "false":
			wantActive = false
		default:
			http.Error(w, "invalid active parameter", http.StatusBadRequest)
			return
		}
		for _, account := range h.accounts {
			if account.Active == wantActive {
				accounts = append(accounts, account)
			}
		}
	} else {
		accounts = append(accounts, h.accounts...)
	}

	writeJSON(w, accounts)
}

func (h accountHandler) writeAccount(w http.ResponseWriter, r *http.Request, id string) {
	index, found := slices.BinarySearchFunc(h.accounts, id, func(account Account, id string) int {
		return strings.Compare(account.ID, id)
	})
	if !found {
		http.NotFound(w, r)
		return
	}
	writeJSON(w, h.accounts[index])
}

func writeJSON(w http.ResponseWriter, value any) {
	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(value); err != nil {
		return
	}
}

func methodNotAllowed(w http.ResponseWriter) {
	w.Header().Set("Allow", http.MethodGet)
	http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
}

