func filterAccounts(accounts []Account, r *http.Request) ([]Account, bool) {
	values, present := r.URL.Query()["active"]
	if !present {
		return slices.Clone(accounts), true
	}
	if len(values) != 1 || (values[0] != "true" && values[0] != "false") {
		return nil, false
	}

	active := values[0] == "true"
	filtered := make([]Account, 0, len(accounts))
	for _, account := range accounts {
